    """Compare the two same-sized noisy panels; mark cells where both contain the same color."""
    h, w = len(grid), len(grid[0])
    # Panels are separated by a solid line. The nonmatching color is discarded;
    # matching non-background cells are shown as 3 against background 9.
    for c in range(w):
        if all(len(row) > c and row[c] == grid[0][c] for row in grid):
            separator = grid[0][c]
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            width = min((len(row) for row in left+right), default=0)
            if width and all(len(row) >= width for row in left+right):
                left = [row[:width] for row in left]
                right = [row[:width] for row in right]
                if len(left) == len(right):
                    out = []
                    for a, b in zip(left, right):
                        out.append([3 if x == y and x != separator else 9 for x, y in zip(a, b)])
                    return out
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and 0 < r < h-1:
            sep = row[0]
